const plants = $input.all().map(r => r.json);
const today = new Date();
today.setHours(0, 0, 0, 0);

const needsWater = [];
const needsFertilizer = [];
const needsRepotting = [];
const upcomingCare = [];

for (const plant of plants) {
  if (!plant.plant_name) continue;

  const waterFreqDays = parseInt(plant.water_every_days) || 7;
  const fertFreqDays = parseInt(plant.fertilize_every_days) || 30;
  const repotFreqDays = parseInt(plant.repot_every_days) || 365;

  const lastWatered = plant.last_watered ? new Date(plant.last_watered) : null;
  const lastFertilized = plant.last_fertilized ? new Date(plant.last_fertilized) : null;
  const lastRepotted = plant.last_repotted ? new Date(plant.last_repotted) : null;

  const daysSinceWater = lastWatered ? Math.floor((today - lastWatered) / 86400000) : waterFreqDays;
  const daysSinceFert = lastFertilized ? Math.floor((today - lastFertilized) / 86400000) : fertFreqDays;
  const daysSinceRepot = lastRepotted ? Math.floor((today - lastRepotted) / 86400000) : 0;

  const waterDue = daysSinceWater >= waterFreqDays;
  const fertDue = daysSinceFert >= fertFreqDays;
  const repotDue = daysSinceRepot >= repotFreqDays;
  const waterDueIn = waterFreqDays - daysSinceWater;
  const fertDueIn = fertFreqDays - daysSinceFert;

  const plantInfo = {
    name: plant.plant_name,
    species: plant.species || '',
    location: plant.location || '',
    potSize: plant.pot_size || '',
    lastWatered: plant.last_watered || 'unknown',
    lastFertilized: plant.last_fertilized || 'unknown',
    lastRepotted: plant.last_repotted || 'unknown',
    daysSinceWater,
    daysSinceFert,
    daysSinceRepot,
    waterFreqDays,
    notes: plant.notes || ''
  };

  if (waterDue) needsWater.push({ ...plantInfo, overdueBy: daysSinceWater - waterFreqDays });
  if (fertDue) needsFertilizer.push(plantInfo);
  if (repotDue) needsRepotting.push(plantInfo);

  if (!waterDue && waterDueIn <= 2) upcomingCare.push({ ...plantInfo, waterDueIn });
  if (!fertDue && fertDueIn <= 5) upcomingCare.push({ ...plantInfo, fertDueIn });
}

const hasTasks = needsWater.length + needsFertilizer.length + needsRepotting.length > 0;

return [{
  json: {
    needsWater,
    needsFertilizer,
    needsRepotting,
    upcomingCare,
    totalPlants: plants.filter(p => p.plant_name).length,
    hasTasks,
    todayDate: today.toISOString().split('T')[0]
  }
}];

