const careNote = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
const schedule = $('Check Care Schedule').first().json;

function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&gt;').replace(/</g,'&lt;'); }

const waterSection = schedule.needsWater.length ? `
  <div style="margin-bottom:18px">
    <div style="font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#2563eb;margin-bottom:10px">💧 Water today (${schedule.needsWater.length})</div>
    ${schedule.needsWater.map(p => `
      <div style="display:flex;justify-content:space-between;align-items:center;padding:8px 0;border-bottom:1px solid #f0f7ff">
        <div>
          <div style="font-size:14px;font-weight:600">${esc(p.name)}</div>
          ${p.species ? `<div style="font-size:12px;color:#888;font-style:italic">${esc(p.species)}</div>` : ''}
          ${p.location ? `<div style="font-size:12px;color:#aaa">${esc(p.location)}</div>` : ''}
        </div>
        <div style="text-align:right">
          <div style="font-size:13px;color:${p.overdueBy > 2 ? '#dc2626' : '#d97706'};font-weight:600">${p.daysSinceWater}d since watered</div>
          ${p.overdueBy > 0 ? `<div style="font-size:11px;color:#dc2626">${p.overdueBy}d overdue</div>` : ''}
        </div>
      </div>`).join('')}
  </div>` : '';

const fertSection = schedule.needsFertilizer.length ? `
  <div style="margin-bottom:18px">
    <div style="font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#16a34a;margin-bottom:10px">🌿 Fertilize today (${schedule.needsFertilizer.length})</div>
    ${schedule.needsFertilizer.map(p => `
      <div style="font-size:14px;padding:6px 0;border-bottom:1px solid #f0fdf4">${esc(p.name)}${p.species ? ` <span style="color:#888;font-size:12px;font-style:italic">${esc(p.species)}</span>` : ''} — <span style="color:#888;font-size:13px">${p.daysSinceFert} days since last fed</span></div>`).join('')}
  </div>` : '';

const repotSection = schedule.needsRepotting.length ? `
  <div style="margin-bottom:18px">
    <div style="font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#9333ea;margin-bottom:10px">🪴 Due for repotting (${schedule.needsRepotting.length})</div>
    ${schedule.needsRepotting.map(p => `
      <div style="font-size:14px;padding:6px 0;border-bottom:1px solid #faf5ff">${esc(p.name)} <span style="color:#888;font-size:12px">${p.potSize ? '— currently in ' + esc(p.potSize) : ''}</span></div>`).join('')}
  </div>` : '';

const careNoteHtml = careNote.replace(/\n/g, '<br>');

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:16px;background:#f5f7f2;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#1a1a1a">
<div style="max-width:520px;margin:0 auto">
  <div style="background:#2d5016;color:#fff;padding:18px 24px;border-radius:10px 10px 0 0">
    <div style="font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#a8c77a;margin-bottom:4px">Plant Care · ${esc(schedule.todayDate)}</div>
    <div style="font-size:18px;font-weight:700">🌱 ${schedule.needsWater.length + schedule.needsFertilizer.length + schedule.needsRepotting.length} tasks today · ${schedule.totalPlants} plants</div>
  </div>
  <div style="background:#fff;padding:20px 24px;border-left:1px solid #eee;border-right:1px solid #eee">
    <div style="font-size:13px;font-weight:700;text-transform:uppercase;letter-spacing:0.4px;color:#888;margin-bottom:8px">Today's note</div>
    <p style="font-size:14px;line-height:1.7;color:#333;margin:0">${careNoteHtml}</p>
  </div>
  <div style="background:#fff;padding:20px 24px;border:1px solid #eee;border-top:3px solid #f0f5ea">
    ${waterSection}${fertSection}${repotSection}
    ${schedule.upcomingCare.length ? `<div style="font-size:12px;color:#aaa;margin-top:10px">Coming up: ${schedule.upcomingCare.map(p => `${esc(p.name)} in ${p.waterDueIn !== undefined ? p.waterDueIn + 'd (water)' : p.fertDueIn + 'd (feed)'}`).join(', ')}</div>` : ''}
  </div>
  <div style="background:#2d5016;color:#567a2c;font-size:11px;padding:12px 24px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">
    Plant Care Agent · ${schedule.totalPlants} plants tracked
  </div>
</div>
</body></html>`;

return [{ json: { html, taskCount: schedule.needsWater.length + schedule.needsFertilizer.length + schedule.needsRepotting.length } }];

const body = $input.first().json.body;
const required = ['plant_name', 'symptoms'];
const missing = required.filter(f => !body[f]);
if (missing.length) {
  return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
}
return [{
  json: {
    valid: true,
    plantName: body.plant_name.trim(),
    species: body.species || '',
    symptoms: body.symptoms.trim().slice(0, 1000),
    environment: body.environment || '',
    lastWatered: body.last_watered || '',
    potType: body.pot_type || '',
    lightCondition: body.light_condition || '',
    replyEmail: body.reply_email || null
  }
}];

