const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let diagnosis;
try {
  diagnosis = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch(e) {
  return [{ json: { error: 'Parse error', raw } }];
}
diagnosis._replyEmail = $('Validate Problem Report').first().json.replyEmail;
diagnosis._symptoms = $('Validate Problem Report').first().json.symptoms;
return [{ json: diagnosis }];
